package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {







    @Test
    public void testIsNumber_Exponents() {
        assertTrue(NumberUtils.isNumber("123e45"));
        assertTrue(NumberUtils.isNumber("123E45"));
        assertTrue(NumberUtils.isNumber("123e+45"));
        assertTrue(NumberUtils.isNumber("123e-45"));
        assertFalse(NumberUtils.isNumber("e123"));
        assertFalse(NumberUtils.isNumber("123e"));
        assertFalse(NumberUtils.isNumber("123e+-45"));
        assertFalse(NumberUtils.isNumber("123e1.2")); // dec in exponent
        assertFalse(NumberUtils.isNumber("123e12e12"));
    }








}

package org.apache.commons.lang3.math;

import java.io.*;
