public class NumberUtils_isNumber_TriageGen0Test {













    @Test
    public void testIsNumber_EdgeCases() {
        // Single sign
        assertFalse(NumberUtils.isNumber("-"));
        assertFalse(NumberUtils.isNumber("+"));

        // Sign in exponent
        assertFalse(NumberUtils.isNumber("123e-"));

        // Mixed invalid characters
        assertFalse(NumberUtils.isNumber("12a3"));
        assertFalse(NumberUtils.isNumber("12 3"));
    }


}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {















    @Test
    public void testIsNumber_ComplexBranchCoverage() {
        // Testing the (i < sz + 1 && allowSigns && !foundDigit) condition logic
        // This happens when we have an 'e' but no digit yet, and we encounter a sign
        assertTrue(NumberUtils.isNumber("1e+2"));

        // Test the specific end-of-loop logic for decimals and digits
        assertTrue(NumberUtils.isNumber("123.")); 
        assertFalse(NumberUtils.isNumber("."));

        // Test hex with negative sign: -0x123
        // chars[0] is '-', start = 1. chars[1] is '0', chars[2] is 'x'.
        assertTrue(NumberUtils.isNumber("-0x123"));
    }
}
